import{_ as i,l as n,o as e,c as o,v as t,p as s,x as l,d as E,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"诚实与校准训练","description":"","frontmatter":{"title":"诚实与校准训练","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/honesty-calibration-training.md","filePath":"llm/honesty-calibration-training.md","lastUpdated":1789023840000}'),A={name:"llm/honesty-calibration-training.md"};function p(c,a,u,m,_,f){const r=n("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="诚实与校准训练" tabindex="-1">诚实与校准训练 <a class="header-anchor" href="#诚实与校准训练" aria-label="Permalink to &quot;诚实与校准训练&quot;">​</a></h1><div class="epigraph"><p>有用压力鼓励把猜测写成事实；诚实训练要让模型在不会时说不会，并且口头置信与对错频率对齐。</p><footer>—— Kadavath 等 Language Models (Mostly) Know What They Know；Lin 等 TruthfulQA；Askell 等 HHH 的诚实轴</footer></div><p><a href="/llm/refusal-training">上一课</a>处理「不该做」。本课处理「该做但可能错」。缺口是：<strong>RLHF 的有用 RM 惩罚「我不确定」，奖励流畅的假答案；拒绝训练又把不确定收成拒答。</strong> 诚实与校准是第三条轴。Kadavath 等人表明模型内部往往知道对错，口头不说。本课写如何把那份知识接到奖励，不重写 <a href="/llm/reward-model">RM</a> 的 BT。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>TruthfulQA 测的是模仿人类常见谬误的诱惑。有用比较里，听起来完整的错答常赢过短而正确的「不知道」。PPO 于是提高幻觉流畅度。校准：当模型说「70% 把握」时，经验正确率应接近 70%。口头概率与内部探针（Kadavath）不是一回事；产品用户只看见口头。</p><p>训练目标要分开：事实正确；承认无知；概率语言校准。用一个标量「诚实分」会重新混成印象。细则课的拆分在这里是必须的。</p><h3 id="引用不是诚实" tabindex="-1">引用不是诚实 <a class="header-anchor" href="#引用不是诚实" aria-label="Permalink to &quot;引用不是诚实&quot;">​</a></h3><p>强制引用会变成格式黑客（假 URL）。诚实是对世界状态的报告态度；引用是可检查的支撑，可当细则一条，不能代替「不知道」。</p><p><span class="marginnote">对抗性提示下的「假对齐」（说检查者爱听的话）与本课相关，但不展开攻击方法。评测用已有的诚实基准。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>数据：知则答、不知则明确不知、含口头置信的样本。奖励：事实轴用检索或人类；无知轴用「不应答却答了」负分；校准轴用可靠性图损失或分桶奖惩。可验证域用校验器当事实轴，另加「未答」选项：空答在低置信题上优于胡答。RL：多目标硬门——事实错误封顶，再优化有用。评测：TruthfulQA、校准 ECE、有用是否因多说不知而崩。</p>',11)),(e(),s(h,null,{default:l(()=>[d(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E9%97%AE%E9%A2%98%22%5D%20--%3E%20K%7B%22%E6%A8%A1%E5%9E%8B%E6%98%AF%E5%90%A6%E5%8F%AF%E8%83%BD%E7%9F%A5%E9%81%93%22%7D%0A%20%20K%20--%3E%7C%E6%98%AF%7C%20ANS%5B%22%E4%BD%9C%E7%AD%94%20%2B%20%E5%8F%AF%E9%80%89%E7%BD%AE%E4%BF%A1%22%5D%0A%20%20K%20--%3E%7C%E5%90%A6%7C%20IDK%5B%22%E6%98%8E%E7%A1%AE%E4%B8%8D%E7%9F%A5%22%5D%0A%20%20ANS%20--%3E%20F%5B%22%E4%BA%8B%E5%AE%9E%E9%87%91%E6%A0%87%22%5D%0A%20%20ANS%20--%3E%20C%5B%22%E6%A0%A1%E5%87%86%EF%BC%9A%E7%BD%AE%E4%BF%A1%20vs%20%E6%AD%A3%E7%A1%AE%E7%8E%87%22%5D%0A%20%20IDK%20--%3E%20U%5B%22%E6%9C%89%E7%94%A8%E6%89%A3%E5%88%86%E8%A6%81%E6%9C%89%E4%B8%8A%E9%99%90%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与 <a href="/llm/dpo">DPO</a>：对「诚实短答 vs 流畅幻觉」造对，比标量 RM 更直接，但要防止模型学会永远不知。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>有用梯度指向完整；诚实梯度指向可证伪的克制。加权决定产品性格。校准训练改变的是概率语言，不自动提高知识——ECE 变好可以靠更少夸张，准确率不动。Kadavath 的探针说明表征里有信号；口头对齐是一层薄映射，RL 可以破坏它（为了有用而说满）。因此诚实轴要协议外金标，进入可扩展监督的监控。</p><p><span class="marginnote">长 CoT 推理模型会在链上自我纠正，答案更诚实，链本身仍可能不忠实。后课拆开。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>医疗法律不能把校准当免责替代。多模态「图里有没有」另有幻觉模式，下一课。工具调用可以把诚实外包给检索与校验器，本课的口头校准仍要，否则工具失败时模型会编。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>有用 RM 奖励流畅幻觉；诚实轴要单独的不知与校准金标。</li><li>口头置信与内部探针不是同一对象。</li><li>拒绝 ≠ 诚实；不知不应默认成安全拒。</li><li>DPO 造「诚实 vs 幻觉」对有效，须防止永远不知。</li><li>出处：Kadavath 等；Lin 等 TruthfulQA；Askell / Bai HHH；Ouyang InstructGPT 的真实轴。</li></ul>',8))])}const D=i(A,[["render",p]]);export{T as __pageData,D as default};
